    13  M3Result  EnsureCodePageNumLines  (IM3Compilation o, u32 i_numLines)
    14  {
    15      M3Result result = m3Err_none;
    16
    17      i_numLines += 2; // room for Bridge
    18
    19      if (NumFreeLines (o->page) < i_numLines)
    20      {
    21          IM3CodePage page = AcquireCodePageWithCapacity (o->runtime, i_numLines);
    22
    23          if (page)
    24          {
    25              m3log (emit, "bridging new code page from: %d %p (free slots: %d) to: %d", o->page->info.sequence, GetPC (o), NumFreeLines (o->page), page->info.sequence);
    26              d_m3Assert (NumFreeLines (o->page) >= 2);
    27
    28              EmitWord (o->page, op_Branch);
    29              EmitWord (o->page, GetPagePC (page));
    30
    31              ReleaseCodePage (o->runtime, o->page);
    32
    33              o->page = page;
    34          }
    35          else result = m3Err_mallocFailedCodePage;
    36      }
    37
    38      return result;
    39  }
