   908  M3Result  m3_GetResults  (IM3Function i_function, uint32_t i_retc, const void * o_retptrs[])
   909  {
   910      IM3FuncType ftype = i_function->funcType;
   911      IM3Runtime runtime = i_function->module->runtime;
   912
   913      if (i_retc != ftype->numRets) {
   914          return m3Err_argumentCountMismatch;
   915      }
   916      if (i_function != runtime->lastCalled) {
   917          return "function not called";
   918      }
   919
   920      u8* s = (u8*) runtime->stack;
   921
   922      for (u32 i = 0; i < ftype->numRets; ++i)
   923      {
   924          switch (d_FuncRetType(ftype, i)) {
   925          case c_m3Type_i32:  *(i32*)o_retptrs[i] = *(i32*)(s); s += 4; break;
   926          case c_m3Type_i64:  s = AlignStackPointerTo64Bits (s); *(i64*)o_retptrs[i] = *(i64*)(s); s += 8; break;
   927          case c_m3Type_f32:  *(f32*)o_retptrs[i] = *(f32*)(s); s += 4; break;
   928          case c_m3Type_f64:  s = AlignStackPointerTo64Bits (s); *(f64*)o_retptrs[i] = *(f64*)(s); s += 8; break;
   929          default: return "unknown return type";
   930          }
